+InterfaceStatsWorker::InterfaceStatsWorker(QObject *parent) :
+    QObject(parent),
+    updateIntervalMsec_(kDefaultUpdateIntervalMsec),
+    timer_(nullptr),
+    statFd_(-1),
+    forkChild_(WS_INVALID_PID),
+    paused_(false)
