+        if (device->hidden)
+            hidden << QString(device->name);
+    }
+    wmem_free(wmem_epan_scope(), prefs.capture_devices_hide);
+    prefs.capture_devices_hide = wmem_strdup(wmem_epan_scope(), hidden.join(",").toUtf8().constData());
+    prefs_main_write();
