-
-    for (sc_entry = sc->cache_list; sc_entry != NULL; sc_entry = g_list_next(sc_entry)) {
-        sc_item = (if_stat_cache_item_t *)sc_entry->data;
-        g_free(sc_item->name);
-        g_free(sc_item);
-    }
-    g_list_free(sc->cache_list);
-    g_free(sc);
